func (f *netMapFreezer) m4(x map[int64]*UserProfile) {
	cnfrt.GrowPool(&f.c1, len(x))
	cnfrt.GrowPool(&f.c2, cnfrt.HashRegion(len(x)))
	if len(x) == 0 {
		return
	}
	var keys []int64
	cacheLarge := len(x) >= 256
	if cacheLarge {
		keys = make([]int64, 0, len(x))
	} else {
		keys = f.k4[:0]
		f.k4 = nil
		if cap(keys) < len(x) {
			keys = make([]int64, 0, max(len(x), 2*cap(keys)))
		}
	}
	for k := range x {
		keys = append(keys, k)
	}
	slices.Sort(keys)
	if cacheLarge {
		f.cached4 = append(f.cached4, keys)
	}
	for _, k := range keys {
		v := x[k]
		f.mn2(v)
	}
	if !cacheLarge {
		f.k4 = keys[:0]
	}
}

func (f *netMapFreezer) e4(x map[int64]*UserProfile) cnfrt.HashSpan {
	if x == nil {
		return cnfrt.HashSpan{KV: cnfrt.NilSpan, Idx: cnfrt.NilSpan}
	}
	n := len(x)
	if n == 0 {
		return cnfrt.HashSpan{}
	}
	var keys []int64
	reuseBuf := true
	if n >= 256 {
		if f.cachedPos4 >= len(f.cached4) {
			cnfrt.Fail(cnfrt.ErrConcurrentModification)
		}
		keys = f.cached4[f.cachedPos4]
		f.cached4[f.cachedPos4] = nil
		f.cachedPos4++
		if len(keys) != n {
			cnfrt.Fail(cnfrt.ErrConcurrentModification)
		}
		reuseBuf = false
	} else {
		// Take the shared key buffer; a nested map of the same type finds it
		// empty and uses its own.
		keys = f.k4[:0]
		f.k4 = nil
		if cap(keys) < n {
			keys = make([]int64, 0, max(n, 2*cap(keys)))
		}
		for k := range x {
			keys = append(keys, k)
		}
		if len(keys) != n {
			cnfrt.Fail(cnfrt.ErrConcurrentModification)
		}
		slices.Sort(keys)
	}
	off := f.reserve(&f.p1, f.c1, n)
	dst := f.s.pool1[off : int(off)+n]
	for i, k := range keys {
		v, ok := x[k]
		if !ok {
			cnfrt.Fail(cnfrt.ErrConcurrentModification)
		}
		dst[i].K = int64(k)
		dst[i].V = f.en2(v)
	}
	region := cnfrt.HashRegion(n)
	ioff := f.reserve(&f.p2, f.c2, region)
	idx := f.s.pool2[ioff : int(ioff)+region]
	mask := uint64(region - 1)
	for i, k := range keys {
		h := cnfrt.HashUint64(uint64(k), f.b.Seed)
		for j := h & mask; ; j = (j + 1) & mask {
			if idx[j] == 0 {
				idx[j] = uint32(i + 1)
				break
			}
		}
	}
	if reuseBuf {
		f.k4 = keys[:0]
	}
	return cnfrt.HashSpan{KV: cnfrt.Span32{Off: off, Len: uint32(n)}, Idx: cnfrt.Span32{Off: ioff, Len: uint32(region)}}
}

