// trackNetMapSnapshot registers a snapshot that owns its string blob (a frozen
// snapshot or one loaded from a private copy) with the leak detector.
func trackNetMapSnapshot(s *NetMapSnapshot, err error) (*NetMapSnapshot, error) {
	if err != nil {
		return nil, err
	}
	s.leak = cnfrt.TrackSnapshot(cnfrt.GlobalLeakDetector(), s, "NetMapSnapshot", s.strBlob, true)
	return s, nil
}

// trackSharedNetMapSnapshot registers a snapshot whose string blob aliases memory it
// does not own (a mapping or a caller's buffer); only the snapshot itself
// is watched.
func trackSharedNetMapSnapshot(s *NetMapSnapshot, err error) (*NetMapSnapshot, error) {
	if err != nil {
		return nil, err
	}
	s.leak = cnfrt.TrackSnapshot(cnfrt.GlobalLeakDetector(), s, "NetMapSnapshot", s.strBlob, false)
	return s, nil
}

// FreezeNetMap freezes the object graph rooted at src into a snapshot.
// Shared pointers are deduplicated and directed cycles are rejected with
// cnfrt.ErrCycleDetected.
func FreezeNetMap(src *NetMap, opts ...cnfrt.FreezeOption) (*NetMapSnapshot, error) {
	return trackNetMapSnapshot(freezeNetMap(cnfrt.ModeDAG, src, opts))
}

// FreezeTreeNetMap freezes src as a tree: no visited set is kept (shared
// pointers are duplicated) and recursion deeper than the maximum depth fails
// with cnfrt.ErrCycleDetected. Because addresses are not recorded, src does
// not need to escape to the heap.
func FreezeTreeNetMap(src *NetMap, opts ...cnfrt.FreezeOption) (*NetMapSnapshot, error) {
	return trackNetMapSnapshot(freezeTreeNetMap(src, opts))
}

// FreezeCyclicNetMap freezes src permitting directed cycles; shared pointers are
// deduplicated.
func FreezeCyclicNetMap(src *NetMap, opts ...cnfrt.FreezeOption) (*NetMapSnapshot, error) {
	return trackNetMapSnapshot(freezeNetMap(cnfrt.ModeCyclic, src, opts))
}

func freezeNetMap(mode cnfrt.FreezeMode, src *NetMap, opts []cnfrt.FreezeOption) (snap *NetMapSnapshot, err error) {
	if src == nil {
		return nil, cnfrt.ErrNilRoot
	}
	cnfrt.Escape(src)
	f := netMapFreezerPool.Get().(*netMapFreezer)
	defer func() {
		cnfrt.Recover(recover(), &err)
		if err != nil {
			snap = nil
		}
		f.reset()
		netMapFreezerPool.Put(f)
	}()
	f.b.Init(mode, 4, opts...)
	f.mn0(src)
	f.allocate()
	id := f.en0(src)
	f.finish()
	runtime.KeepAlive(src)
	s := f.s
	s.rootTable, s.rootID = 0, id
	return s, nil
}

func freezeTreeNetMap(src *NetMap, opts []cnfrt.FreezeOption) (snap *NetMapSnapshot, err error) {
	if src == nil {
		return nil, cnfrt.ErrNilRoot
	}
	f := netMapFreezerPool.Get().(*netMapFreezer)
	defer func() {
		cnfrt.Recover(recover(), &err)
		if err != nil {
			snap = nil
		}
		f.reset()
		netMapFreezerPool.Put(f)
	}()
	f.b.Init(cnfrt.ModeTree, 4, opts...)
	f.mn0(src)
	f.allocate()
	id := f.en0(src)
	f.finish()
	runtime.KeepAlive(src)
	s := f.s
	s.rootTable, s.rootID = 0, id
	return s, nil
}

