func (u *netMapUnfreezer) fill0(id uint32, p *NetMap) {
	r := &u.s.nodesNetMap[id-1]
	p.Self = u.pn1(r.FSelf)
	p.Peers = u.u1(r.FPeers)
	p.Users = u.u4(r.FUsers)
	p.DNS = u.vi0(r.FDNS)
	p.PacketFilter = u.u7(r.FPacketFilter)
	p.Domain = u.s.str(r.FDomain)
	p.CollectedAt = cnfrt.DecodeTime(r.FCollectedAt, u.s.locs)
}

func (u *netMapUnfreezer) pn0(id uint32) *NetMap {
	if id == 0 {
		return nil
	}
	if u.m0 == nil {
		u.m0 = make([]*NetMap, len(u.s.nodesNetMap))
	}
	if p := u.m0[id-1]; p != nil {
		return p
	}
	p := new(NetMap)
	u.m0[id-1] = p
	u.fill0(id, p)
	return p
}

func (u *netMapUnfreezer) vn0(id uint32) (x NetMap) {
	if id == 0 || u.depth > u.s.nodeCount() {
		if u.err == nil {
			u.err = fmt.Errorf("%w: value node cycle", cnfrt.ErrCycleDetected)
		}
		return x
	}
	u.depth++
	u.fill0(id, &x)
	u.depth--
	return x
}

func (u *netMapUnfreezer) fill1(id uint32, p *Node) {
	r := &u.s.nodesNode[id-1]
	p.ID = NodeID(r.FID)
	p.StableID = u.s.str(r.FStableID)
	p.Name = u.s.str(r.FName)
	p.User = u.pn2(r.FUser)
	p.Key = u.s.str(r.FKey)
	p.KeyExpiry = cnfrt.DecodeTime(r.FKeyExpiry, u.s.locs)
	p.Machine = u.s.str(r.FMachine)
	p.DiscoKey = u.s.str(r.FDiscoKey)
	p.Addresses = u.u12(r.FAddresses)
	p.AllowedIPs = u.u12(r.FAllowedIPs)
	p.PrimaryRoutes = u.u12(r.FPrimaryRoutes)
	p.Endpoints = u.u14(r.FEndpoints)
	p.HomeDERP = r.FHomeDERP
	p.Hostinfo = u.vi2(r.FHostinfo)
	p.Created = cnfrt.DecodeTime(r.FCreated, u.s.locs)
	if r.PresentBits&(1<<0) != 0 {
		optVal := cnfrt.DecodeTime(r.FLastSeen, u.s.locs)
		p.LastSeen = &optVal
	}
	if r.PresentBits&(1<<1) != 0 {
		optVal := (r.FOnline != 0)
		p.Online = &optVal
	}
	p.MachineAuthorized = (r.FMachineAuthorized != 0)
	p.Expired = (r.FExpired != 0)
	p.Tags = u.u20(r.FTags)
	p.CapMap = u.u21(r.FCapMap)
}

