func (v *netMapValidator) v20(x cnfrt.Span32, self uint32, tbl int) {
	if err := v.claims[6].Claim(x, -1, true); err != nil {
		v.failErr(err)
		return
	}
	if x.Len == 0 {
		return
	}
	elems := v.s.pool6[int(x.Off) : int(x.Off)+int(x.Len)]
	for i := range elems {
		v.str(elems[i])
	}
}

func (v *netMapValidator) v21(x cnfrt.Span32, self uint32, tbl int) {
	if err := v.claims[7].Claim(x, -1, true); err != nil {
		v.failErr(err)
		return
	}
	if x.Len == 0 {
		return
	}
	kv := v.s.pool7[int(x.Off) : int(x.Off)+int(x.Len)]
	for i := range kv {
		e := &kv[i]
		if !v.str(e.K) || !v.debit(uint64(e.K.Len)+1) {
			return
		}
		if i > 0 && strings.Compare(v.s.rawStr(kv[i-1].K), v.s.rawStr(e.K)) >= 0 {
			v.fail("map keys not strictly ascending")
			return
		}
		v.v20(e.V, self, tbl)
	}
}

